-- --------------------------------------------------------------------
-- 2. SELECT Queries
-- --------------------------------------------------------------------

-- A. All rows and columns
SELECT * FROM customers;

-- B. Selected columns with an alias
SELECT first_name, last_name AS surname, city FROM customers;

-- C. Filter rows with WHERE
SELECT * FROM accounts WHERE account_type = 'SAVINGS' AND balance > 20000;

-- D. Pattern matching (Postgres supports standard LIKE and case-insensitive ILIKE)
SELECT * FROM customers WHERE first_name LIKE 'P%';
SELECT * FROM customers WHERE first_name ILIKE 'p%';

-- E. List filter (IN)
SELECT * FROM customers WHERE city IN ('Mumbai', 'Delhi');

-- F. Range filter (BETWEEN)
SELECT * FROM accounts WHERE balance BETWEEN 30000 AND 100000;

-- G. Sort and Limit: Top 3 highest balances
SELECT account_no, balance FROM accounts ORDER BY balance DESC LIMIT 3;

-- H. Aggregation with GROUP BY
SELECT account_type, COUNT(*) AS total_accounts, SUM(balance) AS total_balance
FROM accounts
GROUP BY account_type;

-- I. Filter groups with HAVING
SELECT customer_id, COUNT(*) AS accounts_held
FROM accounts
GROUP BY customer_id
HAVING COUNT(*) > 1;

-- J. Multi-Table Relational JOIN
SELECT c.customer_id, c.first_name, c.last_name, a.account_no, a.account_type, a.balance
FROM customers c
JOIN accounts a ON a.customer_id = c.customer_id
ORDER BY c.customer_id, a.account_no;


-- --------------------------------------------------------------------
-- 3. UPDATE Operations
-- --------------------------------------------------------------------

-- A. Update single column of one row
UPDATE customers SET city = 'Pune' WHERE customer_id = 3;

-- B. Update multiple columns
UPDATE customers
SET phone = '9988776655', email = 'priya.n@example.com'
WHERE customer_id = 2;

-- C. Update multiple rows
UPDATE customers 
SET kyc_status = 'VERIFIED' 
WHERE customer_id IN (1, 2, 3, 4);

-- D. Calculated update: Credit 4% interest to all savings accounts
UPDATE accounts 
SET balance = balance * 1.04 
WHERE account_type = 'SAVINGS';

-- E. Verify the updated balances
SELECT account_no, account_type, balance 
FROM accounts 
WHERE account_type = 'SAVINGS';


-- --------------------------------------------------------------------
-- 4. DELETE Operations
-- --------------------------------------------------------------------

-- A. Blocked by Foreign Key: Customer 5 still has account 1006
-- Expect error: update or delete on table "customers" violates foreign key constraint
-- DELETE FROM customers WHERE customer_id = 5;

-- B. Create and delete an unreferenced customer
INSERT INTO customers (first_name, last_name, email)
VALUES ('Test', 'User', 'test.user@example.com');

DELETE FROM customers WHERE email = 'test.user@example.com';

-- C. Create and delete a closed, empty account
INSERT INTO accounts (account_no, customer_id, account_type, balance, opened_on, status)
VALUES (1008, 5, 'SAVINGS', 0.00, '2025-01-01', 'CLOSED');

DELETE FROM accounts WHERE status = 'CLOSED' AND balance = 0;

-- D. Confirm final row counts
SELECT COUNT(*) AS total_customers FROM customers; -- 5
SELECT COUNT(*) AS total_accounts  FROM accounts;  -- 7
